(function(root){const core=typeof module!=='undefined'?require('./knowledge-core.js'):root.NTMKnowledgeCore;const api=core.create({"version":1,"pilotConcepts":[{"id":"pe","title":"P/E","answerId":"pe","excerpt":"shortAnswer"},{"id":"forward-basis","title":"Forward och trailing","answerId":"forward","excerpt":"shortAnswer"},{"id":"eps","title":"EPS","answerId":"eps","excerpt":"shortAnswer"},{"id":"dilution","title":"Utspädning","answerId":"dilution","excerpt":"shortAnswer"},{"id":"fcf","title":"Fritt kassaflöde","answerId":"fcf","excerpt":"shortAnswer"},{"id":"margins","title":"Marginaler","answerId":"margins","excerpt":"shortAnswer"},{"id":"growth","title":"Tillväxt och CAGR","answerId":"cagr","excerpt":"shortAnswer"},{"id":"inflation","title":"Inflation","answerId":"inflation","excerpt":"shortAnswer"},{"id":"compounding","title":"Ränta på ränta","answerId":"compounding","excerpt":"shortAnswer"},{"id":"annual-fees","title":"Årlig avgift","answerId":"annual-fees","excerpt":"shortAnswer"},{"id":"valuation-assumptions","title":"Värderingsantaganden","answerId":"thesis","excerpt":"shortAnswer"},{"id":"review-falsification","title":"Pröva din tes","answerId":"thesis","excerpt":"shortAnswer"}],"categories":[{"id":"basics","title":"Grunder & aktier"},{"id":"metrics","title":"Nyckeltal"},{"id":"valuation","title":"Värdering"},{"id":"reports","title":"Rapporter"},{"id":"saving","title":"Sparande & skatt"},{"id":"macro","title":"Makro"},{"id":"risk","title":"Risk & portfölj"}],"entries":[{"id":"pe","slug":"pe-tal","question":"Vad betyder P/E?","shortAnswer":"P/E är aktiekursen delad med vinsten per aktie, EPS. Talet visar vilket pris marknaden sätter på en krona av den angivna årsvinsten.","fullAnswer":"Kontrollera alltid vilken vinst som används: rapporterad historik eller en prognos. En hög multipel kan spegla höga förväntningar, men säger inte att de kommer att infrias. Börja med att göra nämnaren jämförbar mellan bolagen.","example":"En kurs på 150 kr och en års-EPS på 6 kr ger P/E 25. Om kursen står stilla och EPS blir 5 kr stiger P/E till 30 utan någon kursuppgång.","caveats":"P/E är ingen återbetalningsgaranti. Vinsten kan falla, och vid negativ EPS blir en vanlig P/E-jämförelse missvisande. Bransch, skulder och vinstens uthållighet spelar också roll.","category":"valuation","concepts":["pe","eps"],"aliases":["pris vinst","p/e tal","price earnings","vad påverkar p/e"],"relatedEntityIds":["tool-valuation","research-nvda"],"relatedLessonIds":["pe","eps"],"sources":[{"title":"FINRA: Evaluating Stocks","url":"https://www.finra.org/investors/investing/investment-products/stocks/evaluating-stocks","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner","featured":true,"contentVersion":1,"reviewDue":"2027-03-18","practiceId":"check-pe-0"},{"id":"eps","slug":"eps","question":"Vad är EPS?","shortAnswer":"EPS betyder vinst per aktie. Måttet fördelar periodens resultat som tillhör stamaktieägarna på ett vägt genomsnitt av aktierna under perioden.","fullAnswer":"Läs om siffran är grundläggande eller utspädd EPS. Utspädd EPS tar hänsyn till vissa möjliga nya aktier. Det är periodens aktiebas som behövs, inte automatiskt antalet aktier på rapportdagen.","example":"Ett förenklat årsresultat på 60 miljoner kr och 20 miljoner genomsnittliga aktier ger 3 kr i EPS. Med samma resultat och 24 miljoner aktier blir motsvarande tal 2,50 kr.","caveats":"Kvartals-EPS och års-EPS avser olika perioder. Justerad EPS kan dessutom ha andra resultatposter än rapporterad EPS. Läs definition och avstämning innan du jämför eller räknar P/E.","category":"metrics","concepts":["eps","dilution"],"aliases":["vinst per aktie","earnings per share"],"relatedEntityIds":["research-nvda"],"relatedLessonIds":["eps","dilution"],"sources":[{"title":"IFRS Foundation: IAS 33 Earnings per Share","url":"https://www.ifrs.org/issued-standards/list-of-standards/ias-33-earnings-per-share/","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner","featured":true,"contentVersion":1,"reviewDue":"2027-03-18","practiceId":"check-eps-0"},{"id":"cagr","slug":"cagr-total-avkastning","question":"Vad skiljer CAGR från total avkastning?","shortAnswer":"Total avkastning beskriver förändringen över hela perioden. CAGR uttrycker samma start- och slutvärde som en jämn årlig tillväxttakt med ränta på ränta.","fullAnswer":"CAGR är en omräkning av två ändpunkter, inte en beskrivning av hur varje år faktiskt gick. Utan mellanliggande insättningar eller uttag beräknas den som (slutvärde / startvärde) upphöjt till 1 / antal år, minus 1.","example":"10 000 kr som blir 12 100 kr på två år har stigit 21 % totalt. CAGR är 10 % eftersom 10 000 × 1,10 × 1,10 = 12 100.","caveats":"Insättningar kan få kontot att växa utan att investeringarna avkastat lika mycket. Då behövs en metod som hanterar kassaflöden. Ange också om utdelningar, avgifter och skatt ingår.","category":"saving","concepts":["cagr","avkastning"],"aliases":["snittavkastning","årlig avkastning","compound annual growth rate"],"relatedEntityIds":["tool-return"],"relatedLessonIds":["cagr","avkastning"],"sources":[{"title":"Investor.gov: Introduction to Investing, compound growth","url":"https://www.investor.gov/introduction-investing","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner","featured":true,"contentVersion":1,"reviewDue":"2027-03-18","practiceId":"check-cagr-0"},{"id":"gav","slug":"gav","question":"Hur räknar jag GAV?","shortAnswer":"GAV är ditt genomsnittliga anskaffningsvärde per aktie. För enkla köp summerar du kostnaderna och delar med det sammanlagda antalet aktier.","fullAnswer":"Antalet aktier väger varje inköpspris. Ett vanligt medelvärde av två kurser fungerar därför bara när du köpt lika många till båda priserna. Bestäm om courtage ska ingå och använd samma avgränsning hela vägen.","example":"Du köper 10 aktier för 100 kr och 30 för 80 kr. Utan avgifter är GAV (1 000 + 2 400) / 40 = 85 kr, inte 90 kr.","caveats":"Ett lägre GAV visar vad du betalat, inte att nästa köp är attraktivt. Split, försäljningar och andra bolagshändelser kan kräva justeringar. NTM:s inköpskalkyl ersätter inte en skatteberäkning.","category":"saving","concepts":["gav","fees"],"aliases":["genomsnittligt anskaffningsvärde","snittpris","anskaffningspris"],"relatedEntityIds":["tool-purchase"],"relatedLessonIds":["gav","fees"],"sources":[{"title":"Investor.gov: How Fees and Expenses Affect Your Investment Portfolio","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/updated","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"fcf","slug":"fritt-kassaflode","question":"Vad är FCF, fritt kassaflöde?","shortAnswer":"FCF är ett mått på kassaflöde efter vissa investeringar. I en vanlig förenkling räknas det som kassaflöde från den löpande verksamheten minus kontanta investeringar, CapEx.","fullAnswer":"Resultat och betalningar inträffar inte alltid samtidigt. Därför kan ett lönsamt bolag ha svagt kassaflöde, exempelvis när mer pengar binds i kundfordringar. Läs vilken FCF-definition bolaget eller datatjänsten använder.","example":"CFO på 90 och kontant CapEx på 35 ger FCF 55 enligt denna metod. Det är ett kassaflödesmått; det säger inte att hela beloppet kan delas ut.","caveats":"Skuldförfall, leasing och andra åtaganden kan behöva finansieras. En tillfällig minskning av investeringarna kan höja FCF utan att affären blivit starkare. Jämför flera perioder och läs avstämningen.","category":"metrics","concepts":["fcf","financial-statements"],"aliases":["free cash flow","kassaflöde","cfo capex"],"relatedEntityIds":["research-nvda"],"relatedLessonIds":["fcf","financial-statements"],"sources":[{"title":"SEC: Non-GAAP Financial Measures, inklusive FCF","url":"https://www.sec.gov/rules-regulations/staff-guidance/corporation-finance-interpretations/non-gaap-financial-measures","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner","contentVersion":1,"reviewDue":"2027-03-18","practiceId":"growth-cash"},{"id":"peg","slug":"peg-tal","question":"Vad betyder PEG?","shortAnswer":"PEG ställer P/E i relation till en årlig vinsttillväxt uttryckt i procenttal. Det är en förenklad jämförelse mellan priset på vinst och den tillväxt du antar.","fullAnswer":"Vanligen divideras P/E med den förväntade EPS-tillväxten, men både vinstbas och prognosperiod varierar mellan tjänster. Kontrollera om P/E är historiskt eller framåtblickande och hur många års tillväxt prognosen avser.","example":"P/E 30 och antagen årlig EPS-tillväxt på 15 % ger PEG 2: 30 / 15. Här används talet 15, inte decimalen 0,15.","caveats":"PEG under 1 är ingen allmän köpregel. Måttet saknar bland annat explicit risk, skuld och tillväxtens varaktighet. Vid noll eller negativ tillväxt blir den vanliga tolkningen olämplig.","category":"valuation","concepts":["pe","cagr"],"aliases":["price earnings growth","pe tillväxt"],"relatedEntityIds":["tool-valuation"],"relatedLessonIds":["pe","cagr"],"sources":[{"title":"Fidelity: Research glossary, P/E och PEG","url":"https://www.fidelity.com/webcontent/ap010098-etf-content/19.02.0/help/research/learn_er_glossary_3.shtml","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"dilution","slug":"utspadning","question":"Vad betyder dilution eller utspädning?","shortAnswer":"Utspädning innebär att fler aktier kan minska din andel av bolaget om du inte deltar proportionellt. Även vinsten per aktie kan påverkas.","fullAnswer":"Nya aktier kan ges ut för att finansiera verksamheten, genom personalprogram eller när instrument omvandlas till aktier. Skilj ägarandelens utspädning från vad transaktionen gör med bolagets totala värde och framtida resultat.","example":"Du äger 10 av 100 aktier, alltså 10 %. Om 25 nya aktier ges ut och du inte köper fler äger du 10 av 125, vilket är 8 %.","caveats":"En emission kan tillföra användbart kapital; fler aktier är inte automatiskt värdeförstörande. En ren aktiesplit ändrar däremot normalt inte din procentuella ägarandel. Läs emissionsvillkor och aktienoter.","category":"basics","concepts":["dilution","eps"],"aliases":["fler aktier","diluted","nyemission"],"relatedEntityIds":["research-crwv"],"relatedLessonIds":["dilution","eps"],"sources":[{"title":"IFRS Foundation: IAS 33 Earnings per Share","url":"https://www.ifrs.org/issued-standards/list-of-standards/ias-33-earnings-per-share/","reviewedAt":"2026-09-15"},{"title":"Investor.gov: Stocks","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/stocks","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner","contentVersion":1,"reviewDue":"2027-03-18","practiceId":"share-count"},{"id":"market-cap","slug":"borsvarde","question":"Vad är börsvärde?","shortAnswer":"Börsvärdet är marknadsvärdet på bolagets aktier: aktiekursen multiplicerad med antalet utestående aktier. Det är inte samma sak som värdet på hela verksamheten.","fullAnswer":"En låg kurs per aktie betyder därför inte ett litet eller billigt bolag. För bolag med flera aktieslag måste beräkningen hantera respektive antal och pris. Börsvärdet förändras när pris eller aktieantal ändras.","example":"20 miljoner aktier med kursen 50 kr ger ett börsvärde på 1 miljard kr. Ett bolag med kursen 5 kr och 400 miljoner aktier har i stället börsvärdet 2 miljarder.","caveats":"Börsvärdet inkluderar inte en separat skuldjustering. Enterprise value, EV, börjar förenklat med börsvärdet och lägger till skuld samt drar av kassa. Metoden kan kräva fler justeringar.","category":"basics","concepts":["aktier","enterprise-value"],"aliases":["market cap","market capitalization","bolagsvärde"],"relatedEntityIds":["research-nvda"],"relatedLessonIds":["aktier","enterprise-value"],"sources":[{"title":"FINRA: Market Cap Explained","url":"https://www.finra.org/investors/insights/market-cap","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"guidance","slug":"guidance","question":"Vad betyder guidance i en rapport?","shortAnswer":"Guidance är bolagsledningens kommunicerade utsikter för en kommande period. Det kan vara ett intervall för exempelvis omsättning, marginal eller vinst.","fullAnswer":"Skilj ledningens utsikter från analytikernas prognoser och från redan rapporterade resultat. Spara datum, period, mått och förutsättningar. Ett nytt intervall kan vara mer relevant än att den senaste historiska siffran var stark.","example":"Ett fiktivt bolag guidar för nästa kvartals omsättning på 100–110 miljoner. Mittpunkten är 105, men ledningen har inte därmed garanterat ett utfall på exakt 105.","caveats":"Guidance kan ändras eller dras tillbaka. Kontrollera valuta, förvärv och om måtten är justerade. Ett intervall för omsättningen är inte automatiskt en prognos för EPS eller kassaflöde.","category":"reports","concepts":["report","forward-metrics"],"aliases":["utsikter","prognos","outlook","guidning"],"relatedEntityIds":["research-nvda"],"relatedLessonIds":["report","forward-metrics"],"sources":[{"title":"NVIDIA: Exempel på bolagets egen outlook och definitioner","url":"https://investor.nvidia.com/news/press-release-details/2026/NVIDIA-Announces-Financial-Results-for-Fourth-Quarter-and-Fiscal-2026/","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"revenue","slug":"omsattning","question":"Vad är revenue eller omsättning?","shortAnswer":"Revenue betyder intäkter; för ett vanligt rörelsedrivande bolag talar man ofta om omsättning. Det är försäljningen som redovisats under perioden, innan många av verksamhetens kostnader dragits av.","fullAnswer":"När en intäkt redovisas beror på vad bolaget har levererat och de redovisningsregler som gäller. Inbetalningen kan komma vid en annan tidpunkt. Omsättning är därför varken samma sak som vinst eller som pengar på kontot.","example":"Omsättningen ökar från 200 till 230 miljoner. Tillväxten är (230 / 200 − 1) × 100 = 15 %. Det säger ännu inget om hur kostnaderna utvecklats.","caveats":"Tillväxt kan komma från fler sålda enheter, högre priser, förvärv eller valuta. Leta efter en uppdelning innan du kallar hela ökningen organisk tillväxt.","category":"metrics","concepts":["revenue","marginal"],"aliases":["intäkter","försäljning","sales"],"relatedEntityIds":["research-nvda"],"relatedLessonIds":["revenue","marginal"],"sources":[{"title":"IFRS Foundation: IFRS 15 Revenue","url":"https://www.ifrs.org/issued-standards/list-of-standards/ifrs-15-revenue-from-contracts-with-customers/","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"margins","slug":"marginaler","question":"Vad är skillnaden mellan brutto-, rörelse- och nettomarginal?","shortAnswer":"Marginal är ett resultatmått delat med omsättningen. Brutto-, rörelse- och nettomarginal använder olika resultatnivåer och visar därför olika delar av lönsamheten.","fullAnswer":"Bruttomarginalen utgår från bruttoresultatet. Rörelsemarginalen tar även hänsyn till övriga rörelsekostnader. Nettomarginalen använder resultatet efter bland annat finansiering och skatt. Jämför samma nivå och samma period.","example":"Med omsättning 100, bruttoresultat 40, rörelseresultat 15 och nettoresultat 10 blir marginalerna 40 %, 15 % respektive 10 %. Det är tre beskrivningar av samma förenklade resultaträkning.","caveats":"Justerade marginaler kan utesluta kostnader som andra bolag inkluderar. Bransch och redovisningssätt påverkar jämförbarheten. En stigande marginal säger heller inte ensam att kassaflödet förbättras.","category":"metrics","concepts":["marginal","revenue"],"aliases":["bruttomarginal","rörelsemarginal","nettomarginal","lönsamhet"],"relatedEntityIds":["research-nvda"],"relatedLessonIds":["marginal","revenue"],"sources":[{"title":"SEC: Beginners’ Guide to Financial Statements","url":"https://www.sec.gov/about/reports-publications/investorpubsbegfinstmtguide","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner","contentVersion":1,"reviewDue":"2027-03-18","practiceId":"exercise-operating-margin"},{"id":"debt","slug":"skuld-nettoskuld","question":"Vad säger skuld och nettoskuld om ett bolag?","shortAnswer":"Skuld visar åtaganden som måste hanteras. Nettoskuld är vanligen räntebärande skulder minus kassa och likvida medel, men exakt avgränsning måste kontrolleras.","fullAnswer":"Bedöm också när skulderna förfaller, räntan, villkoren och vilken kassa som faktiskt är tillgänglig. Två bolag med samma nettoskuld kan ha helt olika risk om det ena behöver låna om snart.","example":"Skuld 300 och kassa 80 ger förenklad nettoskuld 220. Om 200 förfaller nästa år räcker talet 220 inte för att avgöra om betalningarna kan klaras.","caveats":"Leasing, spärrad kassa och andra åtaganden kan ändra bilden. Att nettoskuld/EBITDA är lågt garanterar inte betalningsförmåga: EBITDA är inte ett mått på fritt tillgängliga pengar.","category":"metrics","concepts":["debt","financial-statements"],"aliases":["net debt","belåning","refinansiering"],"relatedEntityIds":["research-crwv"],"relatedLessonIds":["debt","financial-statements"],"sources":[{"title":"SEC: Beginners’ Guide to Financial Statements","url":"https://www.sec.gov/about/reports-publications/investorpubsbegfinstmtguide","reviewedAt":"2026-09-15"},{"title":"FINRA: Bonds","url":"https://www.finra.org/investors/investing/investment-products/bonds","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"dividends","slug":"utdelning","question":"Är utdelning gratis avkastning?","shortAnswer":"Nej. En utdelning för över värde från bolaget till aktieägarna. Bedöm avkastningen som kursförändring och utdelning tillsammans, med hänsyn till kostnader och skatt.","fullAnswer":"När rätten till utdelningen skiljs av är bolaget, allt annat lika, värt mindre med det utdelade beloppet. Det betyder inte att börskursen måste falla exakt så mycket just den dagen; annan information kan samtidigt påverka.","example":"En aktie kostar 100 kr och delar ut 4 kr. Om kursen därefter är 96 kr har du 96 i aktievärde och 4 kontant före skatt: totalt fortfarande 100.","caveats":"En hög direktavkastning kan bero på en fallande kurs och risk för sänkt utdelning. Historiska utbetalningar är inget löfte om framtida utdelningar. Granska finansieringen bakom dem.","category":"basics","concepts":["avkastning","fcf"],"aliases":["direktavkastning","dividend","utdelningar"],"relatedEntityIds":["tool-compound"],"relatedLessonIds":["avkastning","fcf"],"sources":[{"title":"Investor.gov: Stocks","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/stocks","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"fx","slug":"usd-sek-avkastning","question":"Hur påverkar USD/SEK min avkastning?","shortAnswer":"För en investering i USD påverkas värdet i SEK både av investeringens avkastning och av hur många kronor en dollar kostar. Effekterna multipliceras.","fullAnswer":"Utan mellanliggande kassaflöden blir SEK-avkastningen (1 + avkastning i USD) × (1 + förändring i USD/SEK) − 1. Här betyder högre USD/SEK att dollarn stärkts mot kronan.","example":"Aktien stiger 10 % i USD och USD/SEK faller 8 %. Då blir avkastningen 1,10 × 0,92 − 1 = 1,2 % i SEK, före avgifter och skatt.","caveats":"Addera inte bara procenttalen. Utdelningar, växlingsavgifter och olika köpdatum kräver mer underlag. En valutasäkrad produkt kan bete sig annorlunda, och handelsvalutan avslöjar inte hela den ekonomiska valutaexponeringen.","category":"saving","concepts":["currency","avkastning"],"aliases":["valuta","dollar","valutajusterad avkastning","sek usd"],"relatedEntityIds":["tool-fx"],"relatedLessonIds":["currency","avkastning"],"sources":[{"title":"Investor.gov: International Investing","url":"https://www.investor.gov/introduction-investing/investing-basics/investment-products/international-investing","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner","featured":true},{"id":"isk","slug":"isk-grunder","question":"Hur fungerar skatt på ISK i grunden?","shortAnswer":"ISK beskattas genom en årlig schablonberäkning i stället för separat skatt på varje vinstaffär. Kontots värden och insättningar påverkar underlaget.","fullAnswer":"Du behöver normalt inte redovisa varje försäljning inne i kontot. Skatt kan uppstå även ett år då placeringarna faller i värde. Årsparametrar och den gemensamma grundnivån hämtas här från NTM:s daterade regelregister, inte från en fast siffra i svaret.","example":"Två sparare med samma värde den 31 december kan få olika kapitalunderlag eftersom tidigare kvartalsvärden och insättningar skiljer sig. Slutvärdet ensamt räcker alltså inte för en korrekt kalkyl.","caveats":"Förluster inne i ISK är inte avdragsgilla. Utländsk källskatt och särskilda kontovillkor kan kräva egen kontroll. Välj rätt inkomstår i kalkylatorn och läs Skatteverkets regler för din situation.","category":"saving","concepts":["isk"],"aliases":["investeringssparkonto","schablonskatt","skattefri grundnivå"],"relatedEntityIds":["tool-tax"],"relatedLessonIds":["isk"],"sources":[{"title":"Skatteverket: Skatt på investeringssparkonto","url":"https://www.skatteverket.se/privat/skatter/vardepapper/investeringssparkontoisk.4.5fc8c94513259a4ba1d800037851.html","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner","ruleId":"isk"},{"id":"fees","slug":"courtage","question":"Vad är courtage och hur påverkar det små köp?","shortAnswer":"Courtage är en avgift för en värdepappersaffär. Den kan exempelvis vara procentuell med ett minimibelopp, vilket gör små affärer relativt dyra.","fullAnswer":"Läs prislistan för ditt konto, din marknad och din orderstorlek. Courtage är bara en kostnad: spread, valutaväxling och produktavgifter kan tillkomma. Räkna på både köp och en eventuell framtida försäljning.","example":"Med ett fiktivt minimicourtage på 9 kr kostar ett köp på 300 kr 3 % i courtage. Ett köp på 3 000 kr med samma avgift kostar 0,3 %. Det är ingen faktisk mäklarprislista.","caveats":"Avgiftsfritt courtage betyder inte att all handel är gratis. Fler affärer kan ge högre sammanlagd kostnad. Jämför hela kostnadsbilden och gör inte större köp enbart för att sänka avgiftsprocenten.","category":"saving","concepts":["fees","gav"],"aliases":["mäklaravgift","handelsavgift","kommission"],"relatedEntityIds":["tool-fees","tool-purchase"],"relatedLessonIds":["fees","gav"],"sources":[{"title":"Investor.gov: How Fees and Expenses Affect Your Investment Portfolio","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/updated","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"ttm","slug":"ttm","question":"Vad betyder TTM?","shortAnswer":"TTM betyder trailing twelve months: de senaste tolv månaderna. För ett flödesmått används ofta de fyra senast rapporterade kvartalen.","fullAnswer":"TTM är ett rullande historiskt fönster, inte en prognos. Det kan sluta mitt i ett kalenderår. Kontrollera slutdatumet och använd fristående kvartal så att en ackumulerad halvårs- eller niomånaderssiffra inte dubbelräknas.","example":"Fristående kvartalsintäkter på 20, 25, 30 och 35 ger TTM-intäkter 110. När nästa kvartal på 40 kommer ersätter det det äldsta: 25 + 30 + 35 + 40 = 130.","caveats":"Balansräkningsposter som kassa och skuld är ögonblicksbilder och ska inte summeras till TTM. EPS kräver dessutom hänsyn till aktiebas och definition. Datum är en del av måttet.","category":"reports","concepts":["forward-metrics","financial-statements"],"aliases":["trailing twelve months","rullande tolv månader","lttm"],"relatedEntityIds":["research-nvda"],"relatedLessonIds":["forward-metrics","financial-statements"],"sources":[{"title":"Fidelity: Research glossary, trailing twelve months","url":"https://www.fidelity.com/webcontent/ap010098-etf-content/19.07.0/help/research/learn_er_glossary_2.shtml","reviewedAt":"2026-09-15"},{"title":"SEC: Beginners’ Guide to Financial Statements","url":"https://www.sec.gov/about/reports-publications/investorpubsbegfinstmtguide","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"forward","slug":"forward-trailing-pe","question":"Vad skiljer forward P/E från trailing P/E?","shortAnswer":"Trailing P/E använder historisk vinst. Forward P/E använder en prognos för framtida vinst. Samma aktiekurs kan därför ge två olika multiplar.","fullAnswer":"Forward kan avse nästa räkenskapsår eller nästa tolv månader. En lägre forward-multipel kan bara bero på att prognosen antar högre EPS. Kontrollera också om prognosen är rapporterad eller justerad i sin definition.","example":"Kurs 120 kr och historisk EPS 4 kr ger trailing P/E 30. Med prognostiserad EPS 6 kr blir forward P/E 20. Priset är oförändrat; skillnaden ligger i den förväntade vinsten.","caveats":"Prognosen kan vara fel och ändras efter nästa rapport. Blanda inte historisk EPS för ett bolag med justerad prognos-EPS för ett annat utan att tydligt förklara skillnaden.","category":"valuation","concepts":["forward-metrics","pe"],"aliases":["historiskt pe","framtida pe","prognostiserad vinst","ntm pe"],"relatedEntityIds":["tool-valuation"],"relatedLessonIds":["forward-metrics","pe"],"sources":[{"title":"Fidelity: Research glossary, P/E och PEG","url":"https://www.fidelity.com/webcontent/ap010098-etf-content/19.02.0/help/research/learn_er_glossary_3.shtml","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner","contentVersion":1,"reviewDue":"2027-03-18","practiceId":"check-forward-metrics-0"},{"id":"inflation","slug":"inflation-prisniva","question":"Betyder lägre inflation att priserna sjunker?","shortAnswer":"Nej. Lägre positiv inflation betyder att den allmänna prisnivån stiger långsammare. En fallande allmän prisnivå kallas deflation.","fullAnswer":"Inflation mäter förändringstakten, inte hur höga priserna redan är. Att takten går tillbaka efter en snabb uppgång återställer alltså inte tidigare köpkraft. Enskilda varor kan samtidigt bli billigare eller dyrare än genomsnittet.","example":"En varukorg kostar 100 kr, stiger 10 % till 110 kr och därefter 2 % till 112,20 kr. Inflationstakten har fallit men korgen är fortfarande dyrare än före båda ökningarna.","caveats":"Olika inflationsmått har olika avgränsning. Din egen konsumtion kan skilja sig från indexets varukorg. För sparande behöver nominell avkastning bedömas tillsammans med köpkraftens förändring.","category":"macro","concepts":["inflation"],"aliases":["disinflation","deflation","prisnivå","köpkraft"],"relatedEntityIds":["macro-calendar"],"relatedLessonIds":["inflation"],"sources":[{"title":"Riksbanken: Vad är inflation?","url":"https://www.riksbank.se/sv/penningpolitik/inflationsmalet/vad-ar-inflation/","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner","contentVersion":1,"reviewDue":"2027-03-18","practiceId":"price-level"},{"id":"interest-rates","slug":"styrranta","question":"Hur kan styrräntan påverka investeringar?","shortAnswer":"Styrräntan påverkar andra räntor och därmed finansieringskostnader, sparande och efterfrågan. Effekten på en viss investering beror på verksamheten och vad marknaden redan väntat sig.","fullAnswer":"Högre lånekostnader kan minska utrymmet för konsumtion eller företagsinvesteringar. Samtidigt kan vissa verksamheter gynnas av ett annat ränteläge. Det är därför inte en automatisk regel att varje räntehöjning sänker alla aktier.","example":"Ett förenklat lån på 1 miljon kr med rörlig ränta får 10 000 kr högre årlig räntekostnad om räntan ökar en procentenhet, före skatteffekter och andra villkor.","caveats":"Styrränta och långa marknadsräntor är olika saker. Förändringar verkar med fördröjning, och bundna lån påverkas på andra tider. Skilj ett väntat beslut från en överraskning.","category":"macro","concepts":["interest-rates","inflation"],"aliases":["ränta","räntehöjning","räntekanalen","penningpolitik"],"relatedEntityIds":["macro-calendar"],"relatedLessonIds":["interest-rates","inflation"],"sources":[{"title":"Riksbanken: Så påverkar penningpolitiken inflationen","url":"https://www.riksbank.se/sv/penningpolitik/vad-ar-penningpolitik/sa-paverkar-penningpolitiken-inflationen/","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"bond-yields","slug":"obligationsrantor-aktier","question":"Varför spelar obligationsräntor roll för aktier?","shortAnswer":"Obligationsräntor påverkar avkastningsalternativ och finansieringsvillkor. Högre avkastningskrav kan också sänka nuvärdet av framtida vinster, om allt annat hålls lika.","fullAnswer":"För en obligation med fasta betalningar rör sig pris och marknadens avkastningskrav normalt åt motsatta håll. För aktier tillkommer förändringar i tillväxt, risk och vinst. Orsaken till ränterörelsen är därför viktig.","example":"100 kr som betalas om ett år har nuvärdet cirka 95,24 kr vid 5 % krav och 90,91 kr vid 10 %. Det illustrerar diskontering, inte en prognos för en aktiekurs.","caveats":"Kupongränta, löpande avkastning och avkastning till förfall är olika mått. En stigande obligationsränta kan spegla inflation, kreditrisk eller starkare ekonomi. Ingen enkel procentsats översätter rörelsen till aktiemarknaden.","category":"macro","concepts":["interest-rates","pe"],"aliases":["bond yield","statsobligation","diskonteringsränta","avkastningskrav"],"relatedEntityIds":["tool-valuation"],"relatedLessonIds":["interest-rates","pe"],"sources":[{"title":"FINRA: Bonds","url":"https://www.finra.org/investors/investing/investment-products/bonds","reviewedAt":"2026-09-15"},{"title":"FINRA: Stocks and investment risks","url":"https://www.finra.org/investors/investing/investment-products/stocks","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"earnings","slug":"bra-rapport-fallande-aktie","question":"Varför kan en aktie falla trots en bra rapport?","shortAnswer":"En rapport kan vara stark jämfört med förra året men svagare än marknadens förväntningar. Kursen påverkas också av utsikter, risk och det pris investerarna redan betalat.","fullAnswer":"Skilj historisk förbättring från en positiv överraskning. Läs mer än rubrikens omsättning och EPS: kassaflöde, marginaler, orderingång och framtida utsikter kan ge en annan bild. Orsaken till en dags kursrörelse går inte alltid att fastställa.","example":"Ett fiktivt bolags vinst växer 20 %. Om investerare räknat med 30 % och ledningen sänker utsikterna kan rapporten ändå leda till lägre värdering. Exemplet visar förväntningsskillnaden.","caveats":"En kursreaktion bevisar inte att din långsiktiga tes är rätt eller fel. Jämför rapporten med daterade, mätbara antaganden och var tydlig med vilka förklaringar som bara är hypoteser.","category":"reports","concepts":["report","thesis"],"aliases":["rapportreaktion","förväntningar","kvartalsrapport"],"relatedEntityIds":["research-nvda"],"relatedLessonIds":["report","thesis"],"sources":[{"title":"FINRA: Stocks and investment risks","url":"https://www.finra.org/investors/investing/investment-products/stocks","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"estimates","slug":"analytikerestimat","question":"Vad är analytikerestimat och konsensus?","shortAnswer":"Analytikerestimat är prognoser för exempelvis vinst eller omsättning. Konsensus sammanfattar ett urval av sådana prognoser, ofta med ett genomsnitt eller en median.","fullAnswer":"Konsensus är inte ett rapporterat bolagsresultat och inte nödvändigtvis alla marknadsaktörers förväntan. Tjänster kan använda olika analytiker, uppdateringsdatum, perioder och definitioner. Därför kan två konsensussiffror skilja sig utan att någon är ett enkelt räknefel.","example":"Tre jämförbara EPS-prognoser på 4, 5 och 6 kr har genomsnittet 5 kr. Om en av prognoserna är gammal eller justerad på ett annat sätt blir sammanfattningen svårare att tolka.","caveats":"Visa prognosens datum och källa. Skillnaden mellan högsta och lägsta estimat kan vara viktig. En träff mot konsensus visar inte i sig att aktiens pris är rimligt.","category":"reports","concepts":["forward-metrics","report"],"aliases":["analyst estimates","konsensusprognos","förväntad eps"],"relatedEntityIds":["research-nvda"],"relatedLessonIds":["forward-metrics","report"],"sources":[{"title":"SEC: Analyzing Analyst Recommendations","url":"https://www.sec.gov/about/reports-publications/investorpubsanalystshtm","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"thesis","slug":"investeringstes","question":"Vad ska en enkel investeringstes innehålla?","shortAnswer":"En investeringstes beskriver varför en investering kan fungera, vad som måste bli sant och vad som skulle få dig att ompröva slutsatsen. Den bör gå att följa upp.","fullAnswer":"NTM:s arbetsmetod är att skilja observerade fakta från egna antaganden, koppla antagandena till priset och skriva risker samt kontrollpunkter. Det gör nästa granskning mer konkret än en allmän berättelse om ett bra bolag.","example":"En övningstes kan anta att rörelsemarginalen når 15 % inom fyra kvartal. Du anger vilken rapport som ska kontrolleras och att uthålligt högre kundbortfall skulle tala emot antagandet.","caveats":"En välskriven tes garanterar inte avkastning. Uppföljningsgränser är egna analysval, inte universella köp- eller säljregler. Skriv även vad du inte vet och undvik att ändra gamla antaganden i efterhand.","category":"risk","concepts":["thesis","scenarios"],"aliases":["investment thesis","tes","motbevis","antaganden"],"relatedEntityIds":["workflow-manual-thesis"],"relatedLessonIds":["thesis","scenarios"],"sources":[{"title":"Investor.gov: Researching Investments","url":"https://www.investor.gov/introduction-investing/getting-started/researching-investments","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner","featured":true,"contentVersion":1,"reviewDue":"2027-03-18","practiceId":"build-thesis"},{"id":"diversification","slug":"diversifiering","question":"Vad innebär diversifiering?","shortAnswer":"Diversifiering innebär att sprida exponeringen så att ett enskilt innehav eller en gemensam risk inte dominerar hela portföljen. Antalet innehav är bara en del av bilden.","fullAnswer":"Titta på vad innehaven påverkas av: bransch, kunder, geografi, valuta och finansiering. Flera fonder kan äga samma stora bolag. Även många olika aktier kan samtidigt vara känsliga för samma ekonomiska förändring.","example":"Om ett innehav väger 20 % och halveras medan resten står stilla faller portföljen 10 %. Vid en vikt på 5 % blir bidraget till förlusten 2,5 % under samma antagande.","caveats":"Riskspridning tar inte bort marknadsrisk och lovar ingen vinst. Samband mellan tillgångar kan förändras i stress. Anpassa riskbedömningen till tidshorisont, likviditetsbehov och hur stora förluster du kan bära.","category":"risk","concepts":["diversifiering","position-sizing"],"aliases":["riskspridning","portfölj","sprida risk"],"relatedEntityIds":["tool-purchase"],"relatedLessonIds":["diversifiering","position-sizing"],"sources":[{"title":"Investor.gov: Asset Allocation and Diversification","url":"https://www.investor.gov/introduction-investing/getting-started/asset-allocation","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"eps-comparison","slug":"olika-eps-siffror","question":"Varför skiljer sig EPS mellan olika sajter?","shortAnswer":"Ofta jämför sajterna olika EPS-mått: period, rapporterad eller justerad vinst, grundläggande eller utspädd aktiebas, eller historik mot prognos.","fullAnswer":"Börja vid bolagets egen rapport och anteckna periodens slutdatum, valuta och definition. Följ sedan varje tjänsts metodbeskrivning. En leverantör kan ha uppdaterat den senaste rapporten medan en annan fortfarande använder äldre data.","example":"En sida visar 2 kr för senaste kvartalet och en annan 7 kr för de senaste tolv månaderna. Talen motsäger inte varandra: de besvarar olika frågor. Att bara multiplicera kvartalet med fyra kan missa säsongseffekter.","caveats":"Välj inte automatiskt den högsta EPS-siffran för att få ett lägre P/E. Om justeringar inte går att förklara är jämförelsen osäker. Redovisa skillnaden i stället för att dölja den.","category":"reports","concepts":["eps","forward-metrics"],"aliases":["olika vinst per aktie","adjusted eps","non gaap","gaap","diluted eps"],"relatedEntityIds":["research-nvda"],"relatedLessonIds":["eps","forward-metrics"],"sources":[{"title":"IFRS Foundation: IAS 33 Earnings per Share","url":"https://www.ifrs.org/issued-standards/list-of-standards/ias-33-earnings-per-share/","reviewedAt":"2026-09-15"},{"title":"SEC: Non-GAAP Financial Measures, inklusive FCF","url":"https://www.sec.gov/rules-regulations/staff-guidance/corporation-finance-interpretations/non-gaap-financial-measures","reviewedAt":"2026-09-15"}],"reviewedAt":"2026-09-15","publishedAt":"2026-09-15","status":"published","difficulty":"beginner"},{"id":"compounding","slug":"ranta-pa-ranta","question":"Hur fungerar ränta på ränta?","shortAnswer":"Ränta på ränta innebär att även tidigare avkastning kan ge ny avkastning när den ligger kvar. Nästa periods förändring räknas på det då aktuella kapitalet.","fullAnswer":"I ett förenklat exempel utan insättningar multipliceras startkapitalet med tillväxtfaktorn för varje period. Med jämn årsavkastning blir slutvärdet startkapital × (1 + årstakt) upphöjt till antal år. Månadssparande behöver också ta hänsyn till när varje insättning görs.","example":"100 kr som växer 10 % per år blir 110 kr efter ett år och 121 kr efter två. Den andra ökningen är 11 kr. Exemplet saknar avgift, skatt, inflation och nya insättningar.","caveats":"En jämn takt är ett scenario, inte en prognos. Förluster minskar nästa periods kapitalbas. Kontrollera om resultatet är nominellt eller inflationsjusterat och om avgiften redan har dragits.","category":"saving","concepts":["compounding","cagr"],"aliases":["sammansatt avkastning","compound interest"],"relatedEntityIds":["tool-compound"],"relatedLessonIds":["compounding","cagr"],"sources":[{"title":"Investor.gov: Compound Interest Calculator","url":"https://www.investor.gov/financial-tools-calculators/calculators/compound-interest-calculator","reviewedAt":"2026-09-18"}],"reviewedAt":"2026-09-18","status":"reviewed","difficulty":"beginner","contentVersion":1,"reviewDue":"2027-03-18","practiceId":"cost-timing"},{"id":"annual-fees","slug":"arlig-avgift","question":"Hur påverkar en årlig avgift mitt sparande?","shortAnswer":"En löpande avgift minskar kapitalet som kan växa vidare. Över tid påverkas därför både avgiftsbeloppet och den framtida avkastningen på pengarna som har dragits.","fullAnswer":"Jämför samma startkapital, insättningar, period och avkastning före avgift. Skilj löpande procentavgift från courtage vid ett köp. I NTM:s förenklade årsmodell används faktorn (1 + avkastning) × (1 − avgift); avgiften räknas på värdet efter periodens avkastning.","example":"100 kr, 7 % avkastning och 1 % avgift ger 100 × 1,07 × 0,99 = 105,93 kr i denna modell. Med noll avgift blir det 107 kr. Skillnaden är 1,07 kr efter ett år.","caveats":"Verkliga produkter kan ta avgifter vid andra tidpunkter och ha ytterligare kostnader. Dra inte samma avgift två gånger om din angivna avkastning redan är efter avgift. En låg avgift garanterar inte ett bra investeringsutfall.","category":"saving","concepts":["fees","compounding"],"aliases":["fondavgift","årlig avgift","löpande avgift"],"relatedEntityIds":["tool-fees","tool-compound"],"relatedLessonIds":["fees","compounding"],"sources":[{"title":"Investor.gov: How Fees and Expenses Affect Your Investment Portfolio","url":"https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/updated","reviewedAt":"2026-09-18"}],"reviewedAt":"2026-09-18","status":"reviewed","difficulty":"beginner","contentVersion":1,"reviewDue":"2027-03-18","practiceId":"cost-timing"},{"id":"macro-releases","slug":"tolka-makroslapp","question":"Vad mäter CPI, PCE, payrolls och BNP?","shortAnswer":"CPI och PCE:s prisindex mäter konsumentpriser med olika avgränsning. Payrolls mäter arbetstillfällen i en arbetsgivarundersökning. BNP mäter värdet av slutliga varor och tjänster som produceras inom landet. Kontrollera alltid mått, period och enhet.","fullAnswer":"USA:s CPI följer prisförändringar för en varukorg för urbana konsumenter. PCE:s prisindex omfattar konsumtionsutgifter, även köp för konsumenters räkning. Payrolls räknar anställningar utanför jordbruket; en person med flera jobb kan räknas flera gånger. Arbetslöshetsgraden kommer från en annan undersökning av hushåll. Real BNP justerar för prisförändringar, medan nominell BNP även påverkas av priser. Investerare följer dessa publiceringar för att förstå efterfrågan, prisutveckling och ekonomisk aktivitet. I NTM är detta sammanhang att undersöka, inte en prognos för en enskild aktie.","example":"Syntetiskt index: 100 till 103 är 3 % prisökning. Om nästa jämförbara år slutar på 105,06 är ökningen 2 %; prisnivån har ändå stigit. Ett payrollstal på +100 000 avser förändring i antal jobb, inte procent eller lika många unika personer. Amerikansk kvartals-BNP uttryckt i uppräknad årstakt ska inte läsas som faktisk tillväxt under ett helt år.","caveats":"Skilj månadsförändring från årsförändring, index från procent och totalmått från kärnmått. Säsongsjustering och senare revisioner kan ändra bilden. Kontrollera om föregående värde är ursprungligt eller reviderat; NTM säger okänt när källan inte anger det. Saknad prognos är inte noll och ger ingen beräknad överraskning. Ett utfall ger ingen automatisk marknadsriktning.","category":"macro","concepts":["inflation","interest-rates"],"aliases":["cpi","pce","payrolls","nonfarm payrolls","gdp","bnp","makrosläpp"],"relatedEntityIds":["macro-calendar"],"relatedLessonIds":["inflation","interest-rates"],"sources":[{"title":"BLS: CPI, frågor och svar","url":"https://www.bls.gov/cpi/questions-and-answers.htm","reviewedAt":"2026-09-18"},{"title":"BEA: PCE Price Index","url":"https://www.bea.gov/data/personal-consumption-expenditures-price-index","reviewedAt":"2026-09-18"},{"title":"BLS: Employment Situation, metoder","url":"https://www.bls.gov/bls/empsitquickguide.htm","reviewedAt":"2026-09-18"},{"title":"BEA: Gross Domestic Product","url":"https://www.bea.gov/data/gdp/gross-domestic-product","reviewedAt":"2026-09-18"}],"reviewedAt":"2026-09-18","status":"reviewed","difficulty":"beginner","contentVersion":1,"reviewDue":"2027-03-18","practiceId":"price-level"}]});root.NTMKnowledgeCatalog=api;if(typeof module!=='undefined')module.exports=api;})(typeof window!=='undefined'?window:globalThis);
